export class CommandEncoder {
    constructor(label, device) {
        this.device = device;
        this.descriptor = { label };
        this.wrapped = this.device.wrapped.createCommandEncoder(this.descriptor);
    }
    finish() {
        return this.wrapped.finish();
    }
    computePass(label, passSetter) {
        const pass = this.wrapped.beginComputePass({ label });
        try {
            return passSetter(pass);
        }
        finally {
            pass.end();
        }
    }
    renderPass(descriptor, passSetter) {
        const pass = this.wrapped.beginRenderPass(descriptor);
        try {
            return passSetter(pass);
        }
        finally {
            pass.end();
        }
    }
}
export class Pass {
    constructor(device, label) {
        this.device = device;
        this.label = label;
    }
    enqueue() {
        this.device.enqueue(this.commandBuffer());
    }
    commandBuffer() {
        return this.device.commandBuffer(`${this.label} encoder`, encoder => this.encode(encoder));
    }
    encode(encoder) {
        this.pass(`${this.label} pass`, encoder, pass => this.inlineIn(pass));
        return encoder;
    }
}
export class ComputePass extends Pass {
    constructor(pipeline, groups, encoding = pass => pipeline.addTo(pass, groups)) {
        super(pipeline.layout.device, pipeline.label + ".pass");
        this.pipeline = pipeline;
        this.groups = groups;
        this.encoding = encoding;
    }
    pass(label, encoder, encoding) {
        encoder.computePass(label, encoding);
    }
    withGroups(groups) {
        return new ComputePass(this.pipeline, groups, pass => this.pipeline.addGroupsTo(this.inlineIn(pass), groups));
    }
    dispatchWorkGroups(workgroupCountX, workgroupCountY = 1, workgroupCountZ = 1) {
        return new ComputePass(this.pipeline, this.groups, pass => this.inlineIn(pass).dispatchWorkgroups(workgroupCountX, workgroupCountY, workgroupCountZ));
    }
    dispatchWorkGroupsIndirect(indirectBuffer, indirectOffset) {
        return new ComputePass(this.pipeline, this.groups, pass => this.inlineIn(pass).dispatchWorkgroupsIndirect(indirectBuffer, indirectOffset));
    }
    inlineIn(passEncoder) {
        this.encoding(passEncoder);
        return passEncoder;
    }
}
